  );
  const sentFolderBySpecialUse = useMemo(
    () => accountFolders.find((folder) => (folder.specialUse ?? "").toLowerCase() === "\\sent") ?? null,
    [accountFolders]
  );
  const excludedEverywhereFolderIds = useMemo(
    () =>
      accountFolders
        .filter((folder) => {
