      },
      copyToAccount: ({ threadIds }) =>
        handleCopyMessagesToAccount("copy", resolveIds(threadIds)),
      moveToAccount: ({ threadIds }) =>
        handleCopyMessagesToAccount("move", resolveIds(threadIds))
    };
  }, [
