  useEffect(() => {
    if (typeof window === "undefined" || !("serviceWorker" in navigator)) return;
    const handleServiceWorkerMessage = (event: MessageEvent) => {
      const payload = event.data as
        | {
            type?: string;
            messageId?: string | null;
            accountId?: string;
            reminderId?: string;
            triggerAtMs?: number;
          }
        | null;
      if (!payload?.type) return;
