        logListDebug("info", "thread-related:list-effect:skip", {
          ...debugBase,
          reason: "supports-threads"
        });
        setThreadRelatedMessages([]);
        return;
      }
      if (!includeThreadAcrossFoldersForList) {
        logListDebug("info", "thread-related:list-effect:skip", {
          ...debugBase,
          reason: "cross-folder-disabled"
        });
        setThreadRelatedMessages([]);
        return;
