      void refreshFolders();
      if (payload.accountId === activeAccountId) {
        void refreshMailboxDataRef.current();
      }
    };

    window.addEventListener("storage", handleDetachedMessageDelete);
    return () => {
      window.removeEventListener("storage", handleDetachedMessageDelete);
