        const data = (await res.json()) as { total?: number };
        if (typeof data?.total === "number" && data.total > 0) {
          await recomputeThreadsRef.current();
        } else {
          await syncFolderWithBackgroundRef.current(folderId, true, "full", {
            fullSyncReason:
