"use client";

import { useEffect, useState } from "react";
import { Button, Dialog, Flex, Text, TextArea, TextField } from "@radix-ui/themes";
import { Trash2 } from "lucide-react";
import {
  buildAccountCalendarEventPath,
  buildAccountCalendarEventsPath
} from "@/lib/accountApiPaths";
import type { CalendarEvent } from "@/lib/data";
import {
  inviteInputToMs,
  msToDateLocal,
  msToDateTimeLocal,
  parseLocalScheduleDate,
  recurrenceOptionToRRule,
  rruleToOption,
  shiftEndPreservingDuration,
  type RecurrenceOption
} from "@/lib/composeInvite";
import DialogTitleBar from "@/app/components/mailclient/message/DialogTitleBar";
import CalendarEventScheduleFields from "./CalendarEventScheduleFields";

type Props = {
  open: boolean;
  accountId: string;
  event?: Partial<CalendarEvent>;
  defaultStart?: Date;
  defaultEnd?: Date;
  defaultAllDay?: boolean;
  onClose: () => void;
  onSaved?: (event: CalendarEvent) => void;
  onDeleted?: (eventId: string) => void;
};

export default function EventDialog({
  open,
  accountId,
  event,
  defaultStart,
  defaultEnd,
  defaultAllDay,
  onClose,
  onSaved,
  onDeleted
}: Props) {
  const isEditing = Boolean(event?.id);
  const [summary, setSummary] = useState("");
  const [description, setDescription] = useState("");
  const [location, setLocation] = useState("");
  const [startValue, setStartValue] = useState("");
  const [endValue, setEndValue] = useState("");
  const [allDay, setAllDay] = useState(false);
  const [recurrence, setRecurrence] = useState<RecurrenceOption>("none");
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!open) return;
    const now = defaultStart ?? new Date();
    const end = defaultEnd ?? new Date(now.getTime() + 60 * 60 * 1000);
    const isAllDay = defaultAllDay ?? false;
    setSummary(event?.summary ?? "");
    setDescription(event?.description ?? "");
    setLocation(event?.location ?? "");
    setAllDay(event?.allDay ?? isAllDay);
    setRecurrence(rruleToOption(event?.recurrenceRule));
    setError("");
    if (event?.startAtMs) {
      setStartValue(isAllDay || event.allDay
        ? msToDateLocal(event.startAtMs)
        : msToDateTimeLocal(event.startAtMs));
      setEndValue(event.endAtMs
        ? (isAllDay || event.allDay ? msToDateLocal(event.endAtMs) : msToDateTimeLocal(event.endAtMs))
        : "");
    } else {
      setStartValue(isAllDay ? msToDateLocal(now.getTime()) : msToDateTimeLocal(now.getTime()));
      setEndValue(isAllDay ? msToDateLocal(end.getTime()) : msToDateTimeLocal(end.getTime()));
    }
  }, [open, event, defaultStart, defaultEnd, defaultAllDay]);

  const handleSave = async () => {
    if (!summary.trim()) {
      setError("Title is required.");
      return;
    }
    const startMs = startValue ? inviteInputToMs(startValue, allDay) : Date.now();
    const endMs = endValue ? inviteInputToMs(endValue, allDay) : undefined;
    // monthly-by-day needs the start date to derive its BYDAY ordinal; without
    // it the helper silently downgrades to FREQ=MONTHLY and the user's
    // "Monthly on the Nth weekday" choice is lost on save.
    const rrule =
      recurrenceOptionToRRule(recurrence, parseLocalScheduleDate(startValue)) || undefined;

    setSaving(true);
    setError("");
    try {
      const url = isEditing
        ? buildAccountCalendarEventPath(accountId, event!.id!)
        : buildAccountCalendarEventsPath(accountId);
      const method = isEditing ? "PUT" : "POST";
      const body = {
        id: event?.id,
        eventUid: event?.eventUid,
        summary: summary.trim(),
        description: description.trim() || undefined,
        location: location.trim() || undefined,
        startAtMs: startMs,
        endAtMs: endMs,
        allDay,
        recurrenceRule: rrule,
        sourceType: event?.sourceType ?? "local"
      };
      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body)
      });
      const data = (await res.json()) as { ok: boolean; event?: CalendarEvent; message?: string };
      if (!res.ok || !data.ok) {
        setError(data.message ?? "Failed to save event.");
        return;
      }
      if (data.event) onSaved?.(data.event);
      onClose();
    } catch {
      setError("Failed to save event.");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!isEditing || !event?.id) return;
    setDeleting(true);
    setError("");
    try {
      const res = await fetch(buildAccountCalendarEventsPath(accountId), {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ eventId: event.id })
      });
      if (!res.ok) {
        setError("Failed to delete event.");
        return;
      }
      onDeleted?.(event.id);
      onClose();
    } catch {
      setError("Failed to delete event.");
    } finally {
      setDeleting(false);
    }
  };

  return (
    <Dialog.Root open={open} onOpenChange={(o) => { if (!o) onClose(); }}>
      <Dialog.Content size="3" style={{ maxWidth: 520 }} aria-describedby={undefined}>
        <Flex direction="column" gap="3">
          <DialogTitleBar
            title={isEditing ? "Edit Event" : "New Event"}
            onClose={onClose}
          />

          <Flex direction="column" gap="2">
            <TextField.Root
              placeholder="Event title"
              value={summary}
              onChange={(e) => setSummary(e.target.value)}
              autoFocus
            />
          </Flex>

          <CalendarEventScheduleFields
            startValue={startValue}
            endValue={endValue}
            allDay={allDay}
            recurrenceRule={recurrenceOptionToRRule(recurrence, parseLocalScheduleDate(startValue))}
            location={location}
            disabled={saving || deleting}
            onStartValueChange={(value) => {
              // Slide the end alongside the start so duration is preserved.
              // Editing the end directly (below) is the only way to change duration.
              //
              // Skip the duration-shift when the new value's shape (date-only
              // vs date+time) contradicts the current `allDay` closure — that
              // happens when the All-day toggle just flipped and queued
              // setAllDay; the toggle handler will overwrite endValue itself.
              const nextHasTime = value.includes("T");
              const shapeMatchesAllDay = nextHasTime === !allDay;
              if (!shapeMatchesAllDay) {
                setStartValue(value);
                return;
              }
              const nextEnd = shiftEndPreservingDuration(startValue, value, endValue, allDay);
              setStartValue(value);
              if (nextEnd !== endValue) setEndValue(nextEnd);
            }}
            onEndValueChange={setEndValue}
            onAllDayChange={setAllDay}
            onRecurrenceRuleChange={(value) => setRecurrence(rruleToOption(value))}
            onLocationChange={setLocation}
          />

          <Flex direction="column" gap="1">
            <Text size="1" color="gray">Description</Text>
            <TextArea
              placeholder="Description (optional)"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
            />
          </Flex>

          {error && <Text size="1" color="red">{error}</Text>}

          <Flex justify="between" align="center" gap="2" wrap="wrap">
            {isEditing &&
            (event?.sourceType === "local" ||
              event?.sourceType === "caldav" ||
              event?.sourceType === "sent-invite") ? (
              <Button
                size="2"
                variant="soft"
                color="red"
                onClick={handleDelete}
                disabled={deleting || saving}
              >
                <Trash2 size={14} />
                Delete
              </Button>
            ) : (
              <span />
            )}
            <Flex gap="2">
              <Button size="2" variant="soft" color="gray" onClick={onClose} disabled={saving || deleting}>
                Cancel
              </Button>
              <Button size="2" onClick={handleSave} disabled={saving || deleting || !summary.trim()}>
                {saving ? "Saving…" : isEditing ? "Save" : "Create"}
              </Button>
            </Flex>
          </Flex>
        </Flex>
      </Dialog.Content>
    </Dialog.Root>
  );
}

import { useCallback, useEffect, useState } from "react";
import type { AccountDateFormat } from "@/lib/data";
import { formatAccountMediumDateTime } from "@/lib/dateFormatting";
import { resolveNextReminderOccurrence } from "@/lib/reminderRecurrence";
import {
  CALENDAR_REMINDER_LEAD_OPTIONS,
  deleteCalendarReminder,
  fetchCalendarReminders,
  findActiveCalendarReminderForEvent,
  getCalendarReminderLeadOption,
  upsertCalendarReminder,
  type CalendarReminder
} from "@/app/components/mailclient/utils/calendarReminders";

export type UseEventReminderStateInput = {
  accountId: string;
  eventUid?: string;
  title: string;
  location?: string;
  description?: string;
  messageId?: string;
  startTimezone?: string;
  recurrenceRule?: string;
  recurrenceDates?: number[];
  excludedDates?: number[];
  canonicalStartMs?: number;
  eventEndAtMs?: number;
  dateFormat?: AccountDateFormat;
  onNotice: (message: string) => void;
};

export type UseEventReminderStateResult = {
  existingReminder: CalendarReminder | null;
  reminderModalOpen: boolean;
  setReminderModalOpen: (open: boolean) => void;
  leadOptionValue: string;
  setLeadOptionValue: (value: string) => void;
  savingReminder: boolean;
  deletingReminder: boolean;
  canScheduleReminder: boolean;
  handleScheduleReminder: () => Promise<void>;
  handleDeleteReminder: () => Promise<void>;
};

function formatTriggerDate(date: Date, dateFormat?: AccountDateFormat) {
  return formatAccountMediumDateTime(date.getTime(), dateFormat) ?? "";
}

/**
 * Owns the reminder lifecycle for a single event: discovering an existing
 * reminder on mount, persisting new ones, and removing them. Surface status
 * messages flow to the caller via `onNotice` so the view layer can decide
 * where to display them.
 */
export function useEventReminderState({
  accountId,
  eventUid,
  title,
  location,
  description,
  messageId,
  startTimezone,
  recurrenceRule,
  recurrenceDates,
  excludedDates,
  canonicalStartMs,
  eventEndAtMs,
  dateFormat,
  onNotice
}: UseEventReminderStateInput): UseEventReminderStateResult {
  const [existingReminder, setExistingReminder] = useState<CalendarReminder | null>(null);
  const [reminderModalOpen, setReminderModalOpen] = useState(false);
  const [leadOptionValue, setLeadOptionValue] = useState(CALENDAR_REMINDER_LEAD_OPTIONS[3]?.value ?? "15");
  const [savingReminder, setSavingReminder] = useState(false);
  const [deletingReminder, setDeletingReminder] = useState(false);

  // Start with the same value on the server and the first client render.
  const [nowMs, setNowMs] = useState<number | null>(null);
  useEffect(() => {
    const updateNow = () => setNowMs(Date.now());
    const firstTick = window.setTimeout(updateNow, 0);
    const timer = window.setInterval(updateNow, 1000);
    return () => {
      window.clearTimeout(firstTick);
      window.clearInterval(timer);
    };
  }, []);

  const canScheduleReminder = (() => {
    if (nowMs === null || typeof canonicalStartMs !== "number" || !Number.isFinite(canonicalStartMs)) return false;
    if (!recurrenceRule?.trim()) return canonicalStartMs > nowMs;
    const next = resolveNextReminderOccurrence({
      eventStartAtMs: canonicalStartMs,
      eventEndAtMs: eventEndAtMs,
      leadMinutes: 0,
      recurrenceRule,
      recurrenceDates,
      excludedDates
    }, nowMs);
    return Boolean(next && next.eventStartAtMs > nowMs);
  })();

  const refreshReminder = useCallback(async () => {
    if (
      !accountId ||
      typeof canonicalStartMs !== "number" ||
      !Number.isFinite(canonicalStartMs)
    ) {
      return;
    }
    try {
      const reminders = await fetchCalendarReminders(accountId);
      const found = findActiveCalendarReminderForEvent(reminders, {
        eventUid,
        eventTitle: title,
        eventStartAtMs: canonicalStartMs
      });
      setExistingReminder(found);
      if (found) {
        const val = String(found.leadMinutes);
        const has = CALENDAR_REMINDER_LEAD_OPTIONS.some((o) => o.value === val);
        setLeadOptionValue(has ? val : (CALENDAR_REMINDER_LEAD_OPTIONS[3]?.value ?? "15"));
      }
    } catch {
      // ignore
    }
  }, [accountId, eventUid, title, canonicalStartMs]);

  useEffect(() => { void refreshReminder(); }, [refreshReminder]);

  const handleScheduleReminder = async () => {
    if (
      !accountId ||
      typeof canonicalStartMs !== "number" ||
      !Number.isFinite(canonicalStartMs)
    ) {
      return;
    }
    setSavingReminder(true);
    try {
      const option = getCalendarReminderLeadOption(leadOptionValue);
      const stored = await upsertCalendarReminder(accountId, {
        eventUid,
        eventTitle: title,
        eventLocation: location,
        eventDescription: description,
        eventStartAtMs: canonicalStartMs,
        eventEndAtMs: eventEndAtMs,
        messageId,
        startTimezone,
        recurrenceRule,
        recurrenceDates,
        excludedDates,
        leadMinutes: option.minutes,
        leadLabel: option.label
      });
      const triggerDate = new Date(stored.reminder.triggerAtMs > Date.now() ? stored.reminder.triggerAtMs : Date.now());
      onNotice(
        stored.replaced
          ? `Reminder updated for ${formatTriggerDate(triggerDate, dateFormat)}.`
          : `Reminder scheduled for ${formatTriggerDate(triggerDate, dateFormat)}.`
      );
      setReminderModalOpen(false);
      await refreshReminder();
    } catch {
      onNotice("Failed to save reminder.");
    } finally {
      setSavingReminder(false);
    }
  };

  const handleDeleteReminder = async () => {
    if (!accountId || !existingReminder) return;
    setDeletingReminder(true);
    try {
      await deleteCalendarReminder(accountId, existingReminder.id);
      setExistingReminder(null);
      onNotice("Reminder removed.");
    } catch {
      onNotice("Failed to remove reminder.");
    } finally {
      setDeletingReminder(false);
    }
  };

  return {
    existingReminder,
    reminderModalOpen,
    setReminderModalOpen,
    leadOptionValue,
    setLeadOptionValue,
    savingReminder,
    deletingReminder,
    canScheduleReminder,
    handleScheduleReminder,
    handleDeleteReminder
  };
}

