"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type React from "react";
import type { Message } from "@/lib/data";
import type { MessageGroupMeta } from "./messagelist/listModel";
import { computeGroupMeta } from "./utils/messageHelpers";
import {
  mergeCollapsedGroupsWithMeta,
  mergeCollapsedThreadsWithMessages
} from "./messagelist/listState";
import { mergeLoadedMessageCount, resolveLoadedMessageCount } from "./utils/listCount";
import { logListDebug, summarizeMessageForListDebug } from "./messagelist/listDebug";
import type { SearchBadgesState } from "./useSearchState";
import { buildMessageListQueryUrl } from "./messageListQueryUrl";
import type { ThreadDateSource } from "@/lib/threadDate";
import type { MessageListSortBy } from "@/lib/messageListSort";

type ApiFetch = (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>;

const LIST_DEBUG_SAMPLE_LIMIT = 12;

export type UseMessageDataParams = {
  messagesKey: string;
  activeAccountId: string;
  searchScope: "folder" | "all";
  activeFolderId: string;
  isRelatedSearch: boolean;
  relatedQueryId: string;
  selectedSearchFields: string[];
  searchBadges: SearchBadgesState;
  effectiveSearchBadges: string[];
  currentSearchExcludedFolderIds: string[];
  supportsThreads: boolean;
  groupBy: string;
  threadDateSource: ThreadDateSource;
  sortBy: MessageListSortBy;
  query: string;
  authState: "loading" | "ok" | "unauth";
  apiFetch: ApiFetch;
  readErrorMessage: (res: Response) => Promise<string>;
  reportError: (message: string) => void;
  setRelatedContext: (ctx: { id: string; subject?: string } | null) => void;
  relatedContext: { id: string; subject?: string } | null;
  setCollapsedGroups: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
  setCollapsedThreads: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
  currentKeyRef: React.MutableRefObject<string>;
};

export function useMessageData({
  messagesKey,
  activeAccountId,
  searchScope,
  activeFolderId,
  isRelatedSearch,
  relatedQueryId,
  selectedSearchFields,
  searchBadges,
  effectiveSearchBadges,
  currentSearchExcludedFolderIds,
  supportsThreads,
  groupBy,
  threadDateSource,
  sortBy,
  query,
  authState,
  apiFetch,
  readErrorMessage,
  reportError,
  setRelatedContext,
  relatedContext,
  setCollapsedGroups,
  setCollapsedThreads,
  currentKeyRef
}: UseMessageDataParams) {
  const [authoritativeRevision, setAuthoritativeRevision] = useState(0);
  const [messages, setMessages] = useState<Message[]>([]);
  const [groupMeta, setGroupMeta] = useState<MessageGroupMeta[]>([]);
  const [messagesPage, setMessagesPage] = useState(1);
  const [hasMoreMessages, setHasMoreMessages] = useState(true);
  const [loadedMessageCount, setLoadedMessageCount] = useState(0);
  const [totalMessages, setTotalMessages] = useState<number | null>(null);
  const [loadingMessages, setLoadingMessages] = useState(false);
  const [refreshingMessages, setRefreshingMessages] = useState(false);
  const [messageListError, setMessageListError] = useState<string | null>(null);

  const filteredSearchRefreshTimerRef = useRef<number | null>(null);
  const lastRequestRef = useRef<{ key: string; page: number } | null>(null);
  const messageMutationVersionRef = useRef(0);
  const listReplacementLogFingerprintRef = useRef("");

  // Cleanup filteredSearchRefreshTimer on unmount
  useEffect(() => {
    return () => {
      if (filteredSearchRefreshTimerRef.current !== null) {
        window.clearTimeout(filteredSearchRefreshTimerRef.current);
        filteredSearchRefreshTimerRef.current = null;
      }
    };
  }, []);

  // Reset list state when the query key changes
  useEffect(() => {
    if (filteredSearchRefreshTimerRef.current !== null) {
      window.clearTimeout(filteredSearchRefreshTimerRef.current);
      filteredSearchRefreshTimerRef.current = null;
    }
    setMessages([]);
    setMessagesPage(1);
    setHasMoreMessages(true);
    setLoadedMessageCount(0);
    setTotalMessages(null);
    lastRequestRef.current = null;
    setGroupMeta([]);
    setMessageListError(null);
  }, [messagesKey]);

  const logListReplacement = (
    source: string,
    prevMessages: Message[],
    nextMessages: Message[]
  ) => {
    const prevScoped = prevMessages.filter((msg) => msg.accountId === activeAccountId);
    const nextScoped = nextMessages.filter((msg) => msg.accountId === activeAccountId);
    const nextIds = new Set(nextScoped.map((msg) => msg.id));
    const removed = prevScoped.filter((msg) => !nextIds.has(msg.id));
    const foreign = nextMessages.filter((msg) => msg.accountId !== activeAccountId);
    if (removed.length === 0 && foreign.length === 0) return;
    const removedSample = removed
      .slice(0, LIST_DEBUG_SAMPLE_LIMIT)
      .map((msg) => summarizeMessageForListDebug(msg));
    const foreignSample = foreign
      .slice(0, LIST_DEBUG_SAMPLE_LIMIT)
      .map((msg) => summarizeMessageForListDebug(msg));
    const fingerprint = [
      source,
      activeAccountId,
      activeFolderId,
      searchScope,
      removed.length,
      foreign.length,
      removedSample.map((msg) => msg?.id ?? "").join(",")
    ].join("|");
    if (listReplacementLogFingerprintRef.current === fingerprint) return;
    listReplacementLogFingerprintRef.current = fingerprint;
    logListDebug("warn", "list replacement changed membership", {
      source,
      activeAccountId,
      activeFolderId,
      searchScope,
      previousCount: prevScoped.length,
      nextCount: nextScoped.length,
      removedCount: removed.length,
      foreignCount: foreign.length,
      removedSample,
      foreignSample
    });
  };

  const buildQueryUrl = (page: number) =>
    buildMessageListQueryUrl({
      accountId: activeAccountId,
      page,
      groupBy,
      searchScope,
      activeFolderId,
      currentSearchExcludedFolderIds,
      supportsThreads,
      threadDateSource,
      sortBy,
      isRelatedSearch,
      relatedQueryId,
      query,
      selectedSearchFields,
      searchBadges: { attachments: searchBadges.attachments },
      effectiveSearchBadges
    });

  // Paginated message load effect.
  useEffect(() => {
    const loadMessages = async () => {
      if (!activeAccountId) return;
      if (searchScope === "folder" && !isRelatedSearch && !activeFolderId) return;
      if (loadingMessages || !hasMoreMessages) return;
      if (
        lastRequestRef.current?.key === messagesKey &&
        lastRequestRef.current?.page === messagesPage
      ) {
        return;
      }
      const requestKey = messagesKey;
      const requestMutationVersion = messageMutationVersionRef.current;
      lastRequestRef.current = { key: requestKey, page: messagesPage };
      try {
        setLoadingMessages(true);
        const messagesRes = await apiFetch(buildQueryUrl(messagesPage));
        if (messagesRes.ok) {
          const data = (await messagesRes.json()) as {
            items: Message[];
            hasMore: boolean;
            groups?: { key: string; label: string; count: number }[];
            total?: number;
            baseCount?: number;
            relatedSubject?: string;
          };
          const items = Array.isArray(data?.items) ? data.items.filter(Boolean) : [];
          const foreignItems = items.filter((item) => item.accountId !== activeAccountId);
          if (foreignItems.length > 0) {
            logListDebug("error", "list API returned foreign-account rows", {
              source: "loadMessages",
              activeAccountId,
              foreignCount: foreignItems.length,
              sample: foreignItems
                .slice(0, LIST_DEBUG_SAMPLE_LIMIT)
                .map((item) => summarizeMessageForListDebug(item))
            });
          }
          if (currentKeyRef.current !== requestKey) return;
          if (messageMutationVersionRef.current !== requestMutationVersion) {
            lastRequestRef.current = null;
            return;
          }
          if (isRelatedSearch) {
            setRelatedContext({ id: relatedQueryId, subject: data.relatedSubject });
          } else if (relatedContext) {
            setRelatedContext(null);
          }
          setAuthoritativeRevision(value => value + 1);
          setMessages((prev) => {
            if (messagesPage === 1) {
              logListReplacement("loadMessages-page1", prev, items);
              return items;
            }
            const prevIds = new Set(prev.map((msg) => msg.id));
            const duplicateIncoming = items.filter((msg) => prevIds.has(msg.id));
            if (duplicateIncoming.length > 0) {
              logListDebug("warn", "paged list append contains duplicate ids", {
                source: "loadMessages-append",
                activeAccountId,
                duplicateCount: duplicateIncoming.length,
                sample: duplicateIncoming
                  .slice(0, LIST_DEBUG_SAMPLE_LIMIT)
                  .map((item) => summarizeMessageForListDebug(item))
              });
            }
            return [...prev, ...items];
          });
          setLoadedMessageCount((prev) =>
            mergeLoadedMessageCount({
              page: messagesPage,
              previousCount: prev,
              itemCount: items.length,
              baseCount: data?.baseCount
            })
          );
          setHasMoreMessages(Boolean(data?.hasMore));
          setTotalMessages(typeof data?.total === "number" ? data.total : null);
          if (messagesPage === 1) {
            const nextMeta = Array.isArray(data?.groups)
              ? data.groups
              : computeGroupMeta(items);
            setGroupMeta(nextMeta);
            setCollapsedGroups((prev) => mergeCollapsedGroupsWithMeta(prev, nextMeta));
            setCollapsedThreads((prev) => mergeCollapsedThreadsWithMessages(prev, items));
          }
          setMessageListError(null);
        } else {
          const errorMessage = await readErrorMessage(messagesRes);
          reportError(errorMessage);
          setMessageListError(errorMessage || "Failed to load messages.");
        }
      } catch {
        lastRequestRef.current = null;
        reportError("Failed to load messages.");
        setMessageListError("Failed to load messages.");
      } finally {
        setLoadingMessages(false);
      }
    };

    loadMessages();
    // Dep array intentionally omits query/searchScope/etc. — messagesKey encodes all those values;
    // the reset effect above handles key changes and triggers a fresh page-1 load.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeAccountId, hasMoreMessages, loadingMessages, messagesKey, messagesPage, authState]);

  const refreshMailboxData = async (): Promise<boolean> => {
    if (searchScope === "folder" && !isRelatedSearch && !activeFolderId) {
      return false;
    }
    setRefreshingMessages(true);
    const requestKey = messagesKey;
    const requestMutationVersion = messageMutationVersionRef.current;
    try {
      const messageRes = await apiFetch(buildQueryUrl(1));
      if (!messageRes.ok) {
        const message = await readErrorMessage(messageRes);
        reportError(message || "Failed to refresh mailbox data.");
        setMessageListError(message || "Failed to load messages.");
        return false;
      }
      const messageData = (await messageRes.json()) as {
        items: Message[];
        hasMore: boolean;
        groups?: { key: string; label: string; count: number }[];
        total?: number;
        baseCount?: number;
        relatedSubject?: string;
      };
      const nextMessages = Array.isArray(messageData?.items)
        ? messageData.items.filter(Boolean)
        : [];
      const foreignItems = nextMessages.filter((item) => item.accountId !== activeAccountId);
      if (foreignItems.length > 0) {
        logListDebug("error", "refresh returned foreign-account rows", {
          source: "refreshMailboxData",
          activeAccountId,
          foreignCount: foreignItems.length,
          sample: foreignItems
            .slice(0, LIST_DEBUG_SAMPLE_LIMIT)
            .map((item) => summarizeMessageForListDebug(item))
        });
      }
      if (currentKeyRef.current !== requestKey) {
        return false;
      }
      if (messageMutationVersionRef.current !== requestMutationVersion) {
        return false;
      }
      setAuthoritativeRevision(value => value + 1);
      setMessages((prev) => {
        logListReplacement("refreshMailboxData", prev, nextMessages);
        return nextMessages;
      });
      setLoadedMessageCount(
        resolveLoadedMessageCount(nextMessages.length, messageData?.baseCount)
      );
      setMessagesPage(1);
      setHasMoreMessages(Boolean(messageData?.hasMore));
      setTotalMessages(typeof messageData?.total === "number" ? messageData.total : null);
      const nextMeta = Array.isArray(messageData?.groups)
        ? messageData.groups
        : computeGroupMeta(nextMessages);
      if (isRelatedSearch) {
        setRelatedContext({ id: relatedQueryId, subject: messageData.relatedSubject });
      } else if (relatedContext) {
        setRelatedContext(null);
      }
      setGroupMeta(nextMeta);
      setCollapsedGroups((prev) => mergeCollapsedGroupsWithMeta(prev, nextMeta));
      setCollapsedThreads((prev) => mergeCollapsedThreadsWithMessages(prev, nextMessages));
      setMessageListError(null);
      return true;
    } finally {
      setRefreshingMessages(false);
    }
  };

  const queueFilteredSearchRefresh = (hasFilteredSearchCriteria: boolean) => {
    if (!hasFilteredSearchCriteria) return;
    if (filteredSearchRefreshTimerRef.current !== null) return;
    filteredSearchRefreshTimerRef.current = window.setTimeout(() => {
      filteredSearchRefreshTimerRef.current = null;
      void refreshMailboxData();
    }, 120);
  };

  const markMessagesMutated = useCallback(() => {
    messageMutationVersionRef.current += 1;
  }, []);

  return {
    authoritativeRevision,
    messages,
    setMessages,
    groupMeta,
    setGroupMeta,
    messagesPage,
    setMessagesPage,
    hasMoreMessages,
    setHasMoreMessages,
    loadedMessageCount,
    totalMessages,
    setTotalMessages,
    loadingMessages,
    refreshingMessages,
    messageListError,
    setMessageListError,
    refreshMailboxData,
    queueFilteredSearchRefresh,
    messageMutationVersionRef,
    currentKeyRef,
    markMessagesMutated
  };
}

import { useCallback, useEffect, useRef } from "react";
import { useTranslations } from "next-intl";
import type React from "react";
import { buildAccountFoldersPath, buildAccountMessageActionPath, buildAccountMessagesActionPath } from "@/lib/accountApiPaths";
import type { Folder, Message } from "@/lib/data";
import { applyFlagsToMessage, isFlaggedMessage, hasTodoFlag, hasDoneFlag, getUnsubscribeCapability } from "./utils/messageHelpers";
import {
  computeOptimisticMovedMessage,
  getMessageSubjectForNotice,
  resolveMoveViewTransition
} from "./utils/messageMutation";
import { TODO_FLAG, DONE_FLAG } from "@/lib/messageFlags";
import { applyFolderStreamUpdates } from "./folderStreamUpdates";
import { NOTICE_TIMEOUTS } from "./constants";
import type { UndoMoveTarget } from "./useMessageMoveActions";

type UseMessageMutationsProps = {
  activeAccountId: string;
  searchScope: "folder" | "all";
  viewMessage: Message | null;
  hasFilteredSearchCriteria: boolean;
  apiFetch: (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>;
  readErrorMessage: (res: Response) => Promise<string>;
  reportError: (message: string, meta?: { requestPath?: string; status?: number }) => void;
  pushNotice: (notice: any) => void;
  updateMessagesWithCurrentResultPrune: (
    updater: (message: Message) => Message | null,
    options?: { source?: string }
  ) => void;
  setViewMessage: (msg: Message | null) => void;
  setActiveMessageId: (id: string) => void;
  setFolders: React.Dispatch<React.SetStateAction<any[]>>;
  setPendingMessageActions: React.Dispatch<React.SetStateAction<Set<string>>>;
  evictMessageCaches: (messageIds: string[]) => void;
  shouldKeepMessageInCurrentResults: (message: Message) => boolean;
  undoMoveOperation: (targets: UndoMoveTarget[], accountId: string, successTitle?: string) => void;
  confirmUnsubscribe: (sender: string, listId?: string) => Promise<boolean>;
  applyMoveReconcileSuppression: (messages: Message[]) => void;
  setActiveTopicSuggestionMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  updateThreadCacheWithFlags: (messageId: string, flags: string[]) => void;
  updateThreadCacheWithCategory: (
    messageId: string,
    category: string | null,
    categoryScore: number | null,
    categorySignals: string[]
  ) => void;
  queueFilteredSearchRefresh: (hasCriteria: boolean) => void;
};

type SystemFlag = "seen" | "answered" | "flagged" | "draft" | "deleted";
type MoveReconcileParams = {
  movedMessageId: string;
  destinationFolderId?: string | null;
  destinationMailbox?: string;
  flags?: string[];
  source: string;
  successTitle: string;
  undoSuccessMessage: string;
};

export function useMessageMutations({
  activeAccountId,
  searchScope,
  viewMessage,
  hasFilteredSearchCriteria,
  apiFetch,
  readErrorMessage,
  reportError,
  pushNotice,
  updateMessagesWithCurrentResultPrune,
  setViewMessage,
  setActiveMessageId,
  setFolders,
  setPendingMessageActions,
  evictMessageCaches,
  shouldKeepMessageInCurrentResults,
  undoMoveOperation,
  confirmUnsubscribe,
  applyMoveReconcileSuppression,
  setActiveTopicSuggestionMessages,
  updateThreadCacheWithFlags,
  updateThreadCacheWithCategory,
  queueFilteredSearchRefresh
}: UseMessageMutationsProps) {
  const folderRefreshGeneration = useRef(0);
  useEffect(() => () => { folderRefreshGeneration.current += 1; }, [activeAccountId]);

  const tn = useTranslations("Notifications");
  const reconcileMessageFlags = useCallback((
    message: Message,
    flags: string[],
    source: string
  ) => {
    const updatedMessage = applyFlagsToMessage(message, flags);
    const shouldKeepUpdatedMessage = shouldKeepMessageInCurrentResults(updatedMessage);
    updateMessagesWithCurrentResultPrune(
      (item) => (item.id === message.id ? applyFlagsToMessage(item, flags) : item),
      { source }
    );
    setActiveTopicSuggestionMessages((prev) => {
      if (!prev.some((item) => item.id === message.id)) return prev;
      return prev.map((item) =>
        item.id === message.id ? applyFlagsToMessage(item, flags) : item
      );
    });
    updateThreadCacheWithFlags(message.id, flags);
    if (viewMessage?.id === message.id && !shouldKeepUpdatedMessage) {
      setViewMessage(null);
      setActiveMessageId("");
    }
    return updatedMessage;
  }, [
    setActiveMessageId,
    setActiveTopicSuggestionMessages,
    setViewMessage,
    shouldKeepMessageInCurrentResults,
    updateMessagesWithCurrentResultPrune,
    updateThreadCacheWithFlags,
    viewMessage?.id
  ]);

  const reportResponseError = useCallback(async (res: Response) => {
    const message = await readErrorMessage(res);
    let requestPath: string | undefined;
    try {
      if (res.url) {
        const url = new URL(res.url);
        requestPath = `${url.pathname}${url.search}`;
      }
    } catch {
      // ignore
    }
    reportError(message, { requestPath, status: res.status });
  }, [readErrorMessage, reportError]);

  const requestMessageFlagMutation = useCallback(async (
    messageId: string,
    payload: { value: boolean; flag?: SystemFlag; keyword?: string }
  ) => {
    const res = await apiFetch(buildAccountMessageActionPath(activeAccountId, messageId, "flags"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    if (!res.ok) {
      await reportResponseError(res);
      return null;
    }
    const data = (await res.json()) as { flags?: string[] };
    return data.flags ?? [];
  }, [activeAccountId, apiFetch, reportResponseError]);

  const requestBulkFlagMutation = useCallback(async (
    messageIds: string[],
    payload: { value: boolean; flag?: SystemFlag; keyword?: string }
  ) => {
    const res = await apiFetch(buildAccountMessagesActionPath(activeAccountId, "flags/bulk"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...payload, messageIds })
    });
    if (!res.ok) {
      await reportResponseError(res);
      return null;
    }
    const data = (await res.json()) as {
      results?: Array<{ messageId: string; flags: string[] }>;
      skipped?: Array<{ messageId: string; reason: string }>;
    };
    if (data.skipped && data.skipped.length > 0) {
      pushNotice({
        type: "warning",
        title: tn("skipped", { count: data.skipped.length }),
        description: data.skipped[0]?.reason
      });
    }
    return data.results ?? [];
  }, [activeAccountId, apiFetch, pushNotice, reportResponseError, tn]);

  const reconcileMoveMutation = useCallback((
    message: Message,
    params: MoveReconcileParams
  ) => {
    const {
      movedMessageId,
      destinationFolderId,
      destinationMailbox,
      flags,
      source,
      successTitle,
      undoSuccessMessage
    } = params;
    evictMessageCaches(Array.from(new Set([message.id, movedMessageId])));

    const optimisticParams = {
      movedMessageId,
      destinationFolderId,
      destinationMailbox,
      flags,
      searchScope
    };
    const movedMessage = computeOptimisticMovedMessage(message, optimisticParams);

    updateMessagesWithCurrentResultPrune((item) => {
      if (item.id !== message.id) return item;
      return computeOptimisticMovedMessage(item, optimisticParams);
    }, { source });

    const transition = resolveMoveViewTransition(
      viewMessage,
      message.id,
      movedMessage,
      shouldKeepMessageInCurrentResults
    );
    if (transition.kind === "clear") {
      setViewMessage(null);
      setActiveMessageId("");
    } else if (transition.kind === "retarget") {
      setViewMessage(transition.nextViewMessage);
      setActiveMessageId(transition.nextActiveMessageId);
    }

    const undoTarget: UndoMoveTarget = {
      messageId: movedMessageId,
      restoreFolderId: message.folderId
    };
    pushNotice({
      type: "success",
      title: successTitle,
      description: getMessageSubjectForNotice(message, tn("noSubject")),
      actionKind: destinationFolderId ? "undo" : undefined,
      onAction:
        destinationFolderId
          ? () => undoMoveOperation([undoTarget], activeAccountId, undoSuccessMessage)
          : undefined,
      durationMs: NOTICE_TIMEOUTS.success
    });
  }, [
    activeAccountId,
    evictMessageCaches,
    pushNotice,
    searchScope,
    setActiveMessageId,
    setViewMessage,
    shouldKeepMessageInCurrentResults,
    undoMoveOperation,
    updateMessagesWithCurrentResultPrune,
    viewMessage?.id,
    tn
  ]);

  const handleArchiveMessage = useCallback(async (message: Message) => {
    try {
      applyMoveReconcileSuppression([message]);
      const res = await apiFetch(buildAccountMessageActionPath(activeAccountId, message.id, "archive"), {
        method: "POST"
      });
      if (!res.ok) {
        reportError(await readErrorMessage(res));
        return;
      }
      const data = (await res.json()) as {
        action: "moved";
        archiveFolderId?: string | null;
        archiveMailbox?: string;
        flags?: string[];
        previousMessageId?: string;
        messageId?: string;
      };
      reconcileMoveMutation(message, {
        movedMessageId: data.messageId ?? message.id,
        destinationFolderId: data.archiveFolderId,
        destinationMailbox: data.archiveMailbox,
        flags: data.flags,
        source: "archive-message",
        successTitle: tn("archived"),
        undoSuccessMessage: tn("archiveUndone")
      });
    } catch {
      reportError(tn("archiveFailed"));
    }
  }, [
    activeAccountId,
    apiFetch,
    applyMoveReconcileSuppression,
    readErrorMessage,
    reconcileMoveMutation,
    reportError,
    tn
  ]);

  const handleUnsubscribe = useCallback(
    async (message: Message) => {
      const capability = getUnsubscribeCapability(message);
      if (!capability) return;

      // For one-click, show a confirmation dialog
      if (capability === "one-click") {
        // Parse List-Id from the stored header string
        let listId: string | undefined;
        if (message.listUnsubscribe) {
          const lines = message.listUnsubscribe.split("\\n");
          for (const line of lines) {
            if (line.startsWith("List-Id:")) {
              listId = line.substring("List-Id:".length).trim();
              break;
            }
          }
        }
        const confirmed = await confirmUnsubscribe(message.from, listId);
        if (!confirmed) return;
      }

      setPendingMessageActions((prev) => new Set(prev).add(message.id));
      try {
        const res = await apiFetch(buildAccountMessageActionPath(activeAccountId, message.id, "unsubscribe"), {
          method: "POST"
        });

        if (!res.ok) {
          const errMsg = await readErrorMessage(res);
          reportError(errMsg || "Failed to unsubscribe");
          return;
        }

        const data = (await res.json()) as {
          ok: boolean;
          method: "one-click" | "browser" | "mailto";
          url?: string;
        };

        if (data.method === "one-click") {
          pushNotice({
            type: "success",
            title: tn("unsubscribed"),
            description: tn("unsubscribeSent"),
            durationMs: NOTICE_TIMEOUTS.success
          });
        } else if (data.method === "browser" && data.url) {
          window.open(data.url, "_blank", "noopener,noreferrer");
        } else if (data.method === "mailto" && data.url) {
          window.location.href = data.url;
        }
      } catch (error) {
        reportError(error instanceof Error ? error.message : "Unsubscribe failed");
      } finally {
        setPendingMessageActions((prev) => {
          const next = new Set(prev);
          next.delete(message.id);
          return next;
        });
      }
    },
    [activeAccountId, apiFetch, readErrorMessage, reportError, pushNotice, confirmUnsubscribe, setPendingMessageActions, tn]
  );

  const handleMarkSpam = useCallback(async (message: Message) => {
    setPendingMessageActions((prev) => new Set(prev).add(message.id));
    try {
      applyMoveReconcileSuppression([message]);
      const res = await apiFetch(buildAccountMessageActionPath(activeAccountId, message.id, "spam"), {
        method: "POST"
      });
      if (!res.ok) {
        reportError(await readErrorMessage(res));
        return;
      }
      const data = (await res.json()) as {
        action: "moved";
        junkFolderId?: string | null;
        junkMailbox?: string;
        flags?: string[];
        previousMessageId?: string;
        messageId?: string;
      };
      reconcileMoveMutation(message, {
        movedMessageId: data.messageId ?? message.id,
        destinationFolderId: data.junkFolderId,
        destinationMailbox: data.junkMailbox,
        flags: data.flags,
        source: "mark-spam",
        successTitle: tn("markedSpam"),
        undoSuccessMessage: tn("spamUndone")
      });
    } catch {
      reportError(tn("spamFailed"));
    } finally {
      setPendingMessageActions((prev) => {
        const next = new Set(prev);
        next.delete(message.id);
        return next;
      });
    }
  }, [
    activeAccountId,
    apiFetch,
    applyMoveReconcileSuppression,
    readErrorMessage,
    reconcileMoveMutation,
    reportError,
    setPendingMessageActions,
    tn
  ]);

  const handleMarkNotSpam = useCallback(async (message: Message) => {
    setPendingMessageActions((prev) => new Set(prev).add(message.id));
    try {
      applyMoveReconcileSuppression([message]);
      const res = await apiFetch(buildAccountMessageActionPath(activeAccountId, message.id, "not-spam"), {
        method: "POST"
      });
      if (!res.ok) {
        reportError(await readErrorMessage(res));
        return;
      }
      const data = (await res.json()) as {
        action: "moved";
        inboxFolderId?: string | null;
        inboxMailbox?: string;
        flags?: string[];
        previousMessageId?: string;
        messageId?: string;
      };
      reconcileMoveMutation(message, {
        movedMessageId: data.messageId ?? message.id,
        destinationFolderId: data.inboxFolderId,
        destinationMailbox: data.inboxMailbox,
        flags: data.flags,
        source: "mark-not-spam",
        successTitle: tn("markedNotSpam"),
        undoSuccessMessage: tn("notSpamUndone")
      });
    } catch {
      reportError(tn("notSpamFailed"));
    } finally {
      setPendingMessageActions((prev) => {
        const next = new Set(prev);
        next.delete(message.id);
        return next;
      });
    }
  }, [
    activeAccountId,
    apiFetch,
    applyMoveReconcileSuppression,
    readErrorMessage,
    reconcileMoveMutation,
    reportError,
    setPendingMessageActions,
    tn
  ]);

  // A folder:update can arrive before the mutation response. Never add a
  // local delta to that absolute count: read committed folder counts after a
  // seen transition instead, also covering answered/bulk and watcher-off mode.
  const applyFlagsResults = useCallback((
    pairs: Array<{ message: Message; nextFlags: string[] }>,
    source: string
  ) => {
    const changedFolders = new Set<string>();
    for (const { message, nextFlags } of pairs) {
      const updatedMessage = reconcileMessageFlags(message, nextFlags, source);
      if (Boolean(message.seen) !== Boolean(updatedMessage.seen)) changedFolders.add(message.folderId);
    }
    if (changedFolders.size === 0) return;
    const generation = ++folderRefreshGeneration.current;
    void (async () => {
      try {
        const response = await apiFetch(buildAccountFoldersPath(activeAccountId));
        if (!response.ok) { await reportResponseError(response); return; }
        const folders = await response.json() as Folder[];
        if (generation !== folderRefreshGeneration.current) return;
        const updates = folders.map(folder => ({
          id: folder.id, unseen: folder.unreadCount, exists: folder.count
        }));
        setFolders(previous => applyFolderStreamUpdates(previous, updates));
      } catch {
        reportError("Failed to refresh folders.");
      }
    })();
  }, [activeAccountId, apiFetch, reconcileMessageFlags, reportError, reportResponseError, setFolders]);

  const updateFlagState = useCallback(async (
    message: Message,
    flag: SystemFlag,
    value: boolean
  ) => {
    try {
      const flags = await requestMessageFlagMutation(message.id, { flag, value });
      if (!flags) return;
      applyFlagsResults([{ message, nextFlags: flags }], "update-flag-state");
      queueFilteredSearchRefresh(hasFilteredSearchCriteria);
    } catch {
      reportError(tn("flagFailed"));
    }
  }, [
    applyFlagsResults, hasFilteredSearchCriteria, queueFilteredSearchRefresh, reportError,
    requestMessageFlagMutation, tn
  ]);

  const updateKeywordFlag = useCallback(async (
    message: Message,
    keyword: string,
    value: boolean
  ) => {
    try {
      const flags = await requestMessageFlagMutation(message.id, { keyword, value });
      if (!flags) return;
      applyFlagsResults([{ message, nextFlags: flags }], "update-keyword-flag");
      queueFilteredSearchRefresh(hasFilteredSearchCriteria);
    } catch {
      reportError(tn("keywordFailed"));
    }
  }, [
    applyFlagsResults, hasFilteredSearchCriteria, queueFilteredSearchRefresh, reportError,
    requestMessageFlagMutation, tn
  ]);

  const applyBulkFlagResults = useCallback((
    messages: Message[],
    results: Array<{ messageId: string; flags: string[] }>,
    source: string
  ) => {
    const flagsByMessageId = new Map(results.map((r) => [r.messageId, r.flags]));
    const pairs = messages
      .map((message) => {
        const nextFlags = flagsByMessageId.get(message.id);
        return nextFlags ? { message, nextFlags } : null;
      })
      .filter((pair): pair is { message: Message; nextFlags: string[] } => pair !== null);
    applyFlagsResults(pairs, source);
  }, [applyFlagsResults]);

  const updateFlagStateBulk = useCallback(async (
    messages: Message[],
    flag: SystemFlag,
    value: boolean
  ) => {
    if (messages.length === 0) return;
    try {
      const results = await requestBulkFlagMutation(messages.map((m) => m.id), { flag, value });
      if (!results) return;
      applyBulkFlagResults(messages, results, "update-flag-state-bulk");
      queueFilteredSearchRefresh(hasFilteredSearchCriteria);
    } catch {
      reportError(tn("flagFailed"));
    }
  }, [
    applyBulkFlagResults, hasFilteredSearchCriteria, queueFilteredSearchRefresh, reportError,
    requestBulkFlagMutation, tn
  ]);

  const updateKeywordFlagBulk = useCallback(async (
    messages: Message[],
    keyword: string,
    value: boolean
  ) => {
    if (messages.length === 0) return;
    try {
      const results = await requestBulkFlagMutation(messages.map((m) => m.id), { keyword, value });
      if (!results) return;
      applyBulkFlagResults(messages, results, "update-keyword-flag-bulk");
      queueFilteredSearchRefresh(hasFilteredSearchCriteria);
    } catch {
      reportError(tn("keywordFailed"));
    }
  }, [
    applyBulkFlagResults, hasFilteredSearchCriteria, queueFilteredSearchRefresh, reportError,
    requestBulkFlagMutation, tn
  ]);

  const handleSetCategory = useCallback(async (
    message: Message,
    category: "newsletter" | "notification" | "transactional" | null
  ) => {
    setPendingMessageActions((prev) => new Set(prev).add(message.id));
    try {
      const res = await apiFetch(buildAccountMessageActionPath(activeAccountId, message.id, "category"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ category })
      });
      if (!res.ok) {
        reportError(await readErrorMessage(res));
        return;
      }

      const data = (await res.json()) as {
        ok: boolean;
        message?: Message;
        previousCategory?: string | null;
        nextCategory?: string | null;
      };
      const updated = data.message;
      if (!updated) return;

      const shouldKeepUpdatedMessage = shouldKeepMessageInCurrentResults(updated);
      const applyCategoryPatch = (item: Message): Message => ({
        ...item,
        category: updated.category ?? null,
        categoryScore:
          typeof updated.categoryScore === "number" ? updated.categoryScore : null,
        categorySignals: updated.categorySignals ?? []
      });
      updateMessagesWithCurrentResultPrune(
        (item) => (item.id === message.id ? applyCategoryPatch(item) : item),
        { source: "set-category" }
      );
      setActiveTopicSuggestionMessages((prev) => {
        if (!prev.some((item) => item.id === message.id)) return prev;
        return prev.map((item) =>
          item.id === message.id ? applyCategoryPatch(item) : item
        );
      });
      updateThreadCacheWithCategory(
        message.id,
        updated.category ?? null,
        typeof updated.categoryScore === "number" ? updated.categoryScore : null,
        updated.categorySignals ?? []
      );
      if (viewMessage?.id === message.id && !shouldKeepUpdatedMessage) {
        setViewMessage(null);
        setActiveMessageId("");
      }
      queueFilteredSearchRefresh(hasFilteredSearchCriteria);
      pushNotice({
        type: "success",
        title: category ? tn("categoryUpdated") : tn("categoryRemoved"),
        description: getMessageSubjectForNotice(message, tn("noSubject"))
      });
    } catch {
      reportError(tn("categoryFailed"));
    } finally {
      setPendingMessageActions((prev) => {
        const next = new Set(prev);
        next.delete(message.id);
        return next;
      });
    }
  }, [
    activeAccountId,
    apiFetch,
    hasFilteredSearchCriteria,
    pushNotice,
    queueFilteredSearchRefresh,
    readErrorMessage,
    reportError,
    setActiveMessageId,
    setActiveTopicSuggestionMessages,
    setPendingMessageActions,
    setViewMessage,
    shouldKeepMessageInCurrentResults,
    updateMessagesWithCurrentResultPrune,
    updateThreadCacheWithCategory,
    viewMessage?.id,
    tn
  ]);

  const transitionTodoState = useCallback(async (
    msg: Message,
    fromKeyword: string,
    toKeyword: string
  ): Promise<void> => {
    const removeFlags = await requestMessageFlagMutation(msg.id, {
      keyword: fromKeyword,
      value: false
    });
    if (!removeFlags) return;

    const finalFlags = await requestMessageFlagMutation(msg.id, {
      keyword: toKeyword,
      value: true
    });
    if (!finalFlags) return;

    reconcileMessageFlags(msg, finalFlags, "transition-todo-state");
  }, [
    reconcileMessageFlags,
    requestMessageFlagMutation
  ]);

  const clearTodoFlag = useCallback(async (message: Message) => {
    await updateKeywordFlag(message, TODO_FLAG, false);
  }, [updateKeywordFlag]);

  const toggleTodoFlag = useCallback(async (
    message: Message,
    collapsedThreadMessages?: Message[],
    clickedBadge?: "todo" | "done"
  ) => {
    try {
      if (collapsedThreadMessages && collapsedThreadMessages.length > 0 && clickedBadge) {
        if (clickedBadge === "todo") {
          const todoMessages = collapsedThreadMessages.filter((m) => hasTodoFlag(m));
          if (todoMessages.length > 0) {
            await Promise.all(
              todoMessages.map((m) => transitionTodoState(m, TODO_FLAG, DONE_FLAG))
            );
            queueFilteredSearchRefresh(hasFilteredSearchCriteria);
          }
        } else if (clickedBadge === "done") {
          const doneMessages = collapsedThreadMessages.filter((m) => hasDoneFlag(m));
          if (doneMessages.length > 0) {
            await Promise.all(
              doneMessages.map((m) => transitionTodoState(m, DONE_FLAG, TODO_FLAG))
            );
            queueFilteredSearchRefresh(hasFilteredSearchCriteria);
          }
        }
        return;
      }

      const hasTodo = hasTodoFlag(message);
      const hasDone = hasDoneFlag(message);

      let finalFlags = message.flags ?? [];

      if (hasTodo) {
        const removeFlags = await requestMessageFlagMutation(message.id, {
          keyword: TODO_FLAG,
          value: false
        });
        if (!removeFlags) return;

        const addFlags = await requestMessageFlagMutation(message.id, {
          keyword: DONE_FLAG,
          value: true
        });
        if (!addFlags) return;
        finalFlags = addFlags;
      } else if (hasDone) {
        const removeFlags = await requestMessageFlagMutation(message.id, {
          keyword: DONE_FLAG,
          value: false
        });
        if (!removeFlags) return;

        const addFlags = await requestMessageFlagMutation(message.id, {
          keyword: TODO_FLAG,
          value: true
        });
        if (!addFlags) return;
        finalFlags = addFlags;
      } else {
        const flags = await requestMessageFlagMutation(message.id, {
          keyword: TODO_FLAG,
          value: true
        });
        if (!flags) return;
        finalFlags = flags;
      }

      reconcileMessageFlags(message, finalFlags, "toggle-todo-flag");
      queueFilteredSearchRefresh(hasFilteredSearchCriteria);
    } catch {
      reportError(tn("todoFailed"));
    }
  }, [
    hasFilteredSearchCriteria, queueFilteredSearchRefresh, reconcileMessageFlags, reportError,
    requestMessageFlagMutation, transitionTodoState, tn
  ]);

  const toggleFlaggedFlag = useCallback(async (
    message: Message,
    collapsedThreadMessages?: Message[]
  ) => {
    if (collapsedThreadMessages && collapsedThreadMessages.length > 0) {
      const flaggedMessages = collapsedThreadMessages.filter((m) => isFlaggedMessage(m));
      if (flaggedMessages.length > 0) {
        await Promise.all(
          flaggedMessages.map((m) => updateFlagState(m, "flagged", false))
        );
      }
      return;
    }
    await updateFlagState(message, "flagged", !isFlaggedMessage(message));
  }, [updateFlagState]);

  return {
    handleArchiveMessage,
    handleUnsubscribe,
    handleMarkSpam,
    handleMarkNotSpam,
    updateFlagState,
    updateFlagStateBulk,
    updateKeywordFlag,
    updateKeywordFlagBulk,
    handleSetCategory,
    transitionTodoState,
    clearTodoFlag,
    toggleTodoFlag,
    toggleFlaggedFlag
  };
}

